def hidden_rule_fn(state):
    def toro_delta(p, q):
        dx = (q[0] - p[0]) % 8
        if dx > 4:
            dx -= 8
        dy = (q[1] - p[1]) % 8
        if dy > 4:
            dy -= 8
        return dx, dy

    def find_nearest(p, types):
        """Find nearest particle of given types from position p."""
        best_dist = float('inf')
        best_pos = None
        for other in state:
            if other['type'] in types:
                dx, dy = toro_delta(p, (other['x'], other['y']))
                dist = dx*dx + dy*dy
                if dist < best_dist or (dist == best_dist and (best_pos is None or (other['x'], other['y']) < best_pos)):
                    best_dist = dist
                    best_pos = (other['x'], other['y'])
        return best_pos

    next_state = []
    for particle in state:
        ptype = particle['type']
        px, py = particle['x'], particle['y']

        if ptype == 'BRANT':
            # Move towards nearest CLORF
            nearest = find_nearest((px, py), ['CLORF'])
            if nearest is None:
                nx, ny = px, py
            else:
                dx, dy = toro_delta((px, py), nearest)
                dx = max(-1, min(1, dx))
                dy = max(-1, min(1, dy))
                nx = (px + dx) % 8
                ny = (py + dy) % 8

        elif ptype == 'CLORF':
            # Move towards nearest VEXON
            nearest = find_nearest((px, py), ['VEXON'])
            if nearest is None:
                nx, ny = px, py
            else:
                dx, dy = toro_delta((px, py), nearest)
                dx = max(-1, min(1, dx))
                dy = max(-1, min(1, dy))
                nx = (px + dx) % 8
                ny = (py + dy) % 8

        elif ptype == 'VEXON':
            # Move away from nearest BRANT
            nearest = find_nearest((px, py), ['BRANT'])
            if nearest is None:
                nx, ny = px, py
            else:
                dx, dy = toro_delta((px, py), nearest)
                dx = max(-1, min(1, -dx))
                dy = max(-1, min(1, -dy))
                nx = (px + dx) % 8
                ny = (py + dy) % 8

        next_state.append({'type': ptype, 'x': nx, 'y': ny})

    return next_state
